        label: () => {
          if (notes2.ready()) return "Send out a post";
          const host = notes2.host?.() ?? "your sign-in address";
          return notes2.unanswered?.() ? `Sending out a post isn't available: ${host} didn't answer` : `Send out a post: sign in at ${host} first`;
        },
